package br.com.marquesautodetail.api.empresa;
import br.com.marquesautodetail.api.empresa.dto.*;import br.com.marquesautodetail.api.endereco.Endereco;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class EmpresaService{ private final EmpresaRepository repo; public EmpresaService(EmpresaRepository repo){this.repo=repo;} public List<EmpresaResponse> listarProximas(Double lat,Double lng){return repo.findAll().stream().map(e->toResponse(e,lat,lng)).sorted(Comparator.comparing(EmpresaResponse::distanciaKm,Comparator.nullsLast(Double::compareTo))).toList();} public Empresa buscar(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Empresa não encontrada"));} public EmpresaResponse buscarResponse(Long id){return toResponse(buscar(id),null,null);} @Transactional public EmpresaResponse atualizar(Long id,EmpresaRequest r){Empresa e=buscar(id); aplicar(e,r);return toResponse(repo.save(e),null,null);} private void aplicar(Empresa e,EmpresaRequest r){if(r.nomeFantasia()!=null)e.setNomeFantasia(r.nomeFantasia()); if(r.descricao()!=null)e.setDescricao(r.descricao()); if(r.telefone()!=null)e.setTelefone(r.telefone()); if(r.cnpj()!=null)e.setCnpj(r.cnpj()); if(r.latitude()!=null)e.setLatitude(r.latitude()); if(r.longitude()!=null)e.setLongitude(r.longitude()); if(r.aberta()!=null)e.setAberta(r.aberta()); Endereco end=e.getEndereco()!=null?e.getEndereco():new Endereco(); if(r.cep()!=null)end.setCep(r.cep()); if(r.rua()!=null)end.setRua(r.rua()); if(r.numero()!=null)end.setNumero(r.numero()); if(r.bairro()!=null)end.setBairro(r.bairro()); if(r.cidade()!=null)end.setCidade(r.cidade()); if(r.estado()!=null)end.setEstado(r.estado()); e.setEndereco(end);} public EmpresaResponse toResponse(Empresa e,Double lat,Double lng){Endereco end=e.getEndereco(); String endereco=end==null?"":String.join(", ", java.util.stream.Stream.of(end.getRua(),end.getNumero()).filter(Objects::nonNull).filter(s->!s.isBlank()).toList()); String bairro=end!=null?end.getBairro():null; Double d=(lat!=null&&lng!=null&&e.getLatitude()!=null&&e.getLongitude()!=null)?distanciaKm(lat,lng,e.getLatitude(),e.getLongitude()):null; return new EmpresaResponse(e.getId(),e.getNomeFantasia(),e.getDescricao(),e.getTelefone(),endereco,bairro,e.getLatitude(),e.getLongitude(),e.getMediaAvaliacao(),e.getAberta(),d);} private double distanciaKm(double lat1,double lon1,double lat2,double lon2){double R=6371.0; double dLat=Math.toRadians(lat2-lat1),dLon=Math.toRadians(lon2-lon1); double a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(Math.toRadians(lat1))*Math.cos(Math.toRadians(lat2))*Math.sin(dLon/2)*Math.sin(dLon/2); return Math.round((R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)))*10.0)/10.0;} }
